#include "support_m11.h"
static char *read_all(const char *path){FILE *f=fopen(path,"rb");if(!f)return NULL;if(fseek(f,0,SEEK_END))return NULL;long n=ftell(f);if(n<0)return NULL;rewind(f);char *b=malloc((size_t)n+1u);if(!b)return NULL;if(fread(b,1u,(size_t)n,f)!=(size_t)n||fclose(f))return NULL;b[n]=0;return b;}
static int work_diagnostic(const DoeCompilerDiagnostic *d,size_t length){CHECK(d->status==DOE_COMPILER_UNSUPPORTED,"public work exhaustion status");CHECK(!strcmp(d->message,"uniformity analysis work limit exceeded"),"public work exhaustion diagnostic");CHECK(d->offset<length&&d->line>=1u&&d->column>=1u,"public original source location");return 0;}
int main(int argc,char **argv){CHECK(argc==3,"arguments");char *bad=read_all(argv[1]),*good=read_all(argv[2]);CHECK(bad&&good,"source input");CHECK(native_allocator_control()==0,"allocator control");Client c;CHECK(client_new(&c,&generous)==0,"public typed client");DoeCompilerTypedResult r;CHECK(invoke(&c,good,strlen(good),7u,NULL,&r)==DOE_COMPILER_OK,"no-barrier same-shape measurement bypasses work ceiling");Bulk b;CHECK(bulk_new(&b,&r.required)==0,"hardcap bulk");const unsigned modes[]={1u,2u,3u,5u,6u,7u};
 for(unsigned i=0;i<COUNT(modes);i++){unsigned mode=modes[i];DoeCompilerTypedOutputs o=selected(&b,mode);bulk_mark(&b);errno=23791;CHECK(invoke(&c,bad,strlen(bad),mode,(mode&4u)?NULL:&o,&r)==DOE_COMPILER_UNSUPPORTED&&errno==23791,"all modes hard-cap rejection and errno");CHECK(work_diagnostic(&r.diagnostic,strlen(bad))==0&&failure_result(&r,DOE_COMPILER_UNSUPPORTED,0)==0,"typed exact work diagnostic");CHECK(r.exhausted_pool==0u&&r.minimum_pool_capacity==0u&&bulk_unchanged(&b)&&guard_ok(&c.workspace),"typed atomic hardcap failure");CHECK(invoke(&c,good,strlen(good),mode,(mode&4u)?NULL:&o,&r)==DOE_COMPILER_OK,"same pools no-barrier recovery");}
 bulk_free(&b);client_free(&c);
 const DoeCompilerJobCapacities cap={65536u,8192u,1024u,4096u,65536u,32u,16u};DoeCompilerWorkspaceRequirements req;CHECK(doe_compiler_job_requirements(3u,&cap,sizeof(cap),&req,sizeof(req))==DOE_COMPILER_OK,"job query");Guard w,words;CHECK(guard_new(&w,req.size_bytes)==0&&guard_new(&words,65536u*4u)==0,"job guards");DoeCompilerResultV2 r2;CHECK(doe_compiler_compile_job(3u,&cap,sizeof(cap),w.data,w.bytes,bad,strlen(bad),(uint32_t*)words.data,65536u,&r2,sizeof(r2))==DOE_COMPILER_UNSUPPORTED,"job public shared hardcap");CHECK(work_diagnostic(&r2.diagnostic,strlen(bad))==0&&r2.word_count==0u&&bytes_are(&r2.reflection,sizeof(r2.reflection),0)&&bytes_are(words.data,words.bytes,MARK),"job atomic hardcap");CHECK(doe_compiler_compile_job(3u,&cap,sizeof(cap),w.data,w.bytes,good,strlen(good),(uint32_t*)words.data,65536u,&r2,sizeof(r2))==DOE_COMPILER_OK,"job no-barrier same-shape pass");CHECK(guard_ok(&w)&&guard_ok(&words),"job hardcap redzones");guard_free(&w);
 CHECK(doe_compiler_workspace_requirements(2u,&req,sizeof(req))==DOE_COMPILER_OK&&guard_new(&w,req.size_bytes)==0,"fixed query");guard_mark(&words);CHECK(doe_compiler_compile_v2(2u,w.data,w.bytes,bad,strlen(bad),(uint32_t*)words.data,65536u,&r2,sizeof(r2))==DOE_COMPILER_INPUT_ERROR,"fixed profile rejects earlier source pool, not falsely work-limit");CHECK(r2.word_count==0u&&bytes_are(words.data,words.bytes,MARK),"fixed early failure atomic");DoeCompilerResult r1;CHECK(doe_compiler_compile(1u,bad,strlen(bad),(uint32_t*)words.data,65536u,&r1,sizeof(r1))==DOE_COMPILER_INPUT_ERROR,"ABI1 earlier fixed source pool");CHECK(r1.word_count==0u&&bytes_are(words.data,words.bytes,MARK),"ABI1 early failure atomic");guard_free(&w);guard_free(&words);free(good);free(bad);CHECK(atomic_load(&native_allocations)==0u,"typed public compile no allocator calls");puts("PASS default67108864 work cap ABI3/all6 ABI4 modes; same-capacity no-barrier twins pass; ABI1/v2 earlier fixed-token rejection preserved");return 0;}
